import fs from'node:fs';import assert from'node:assert/strict';import{createBodyAdapter}from'./load-adapter.mjs';import{point,mul,sub,norm}from'./math.mjs';const a=createBodyAdapter(),z=a.evaluate(a.zeroState()),s=a.zeroState();s.pose[46]=Math.PI/2;const r=a.evaluate(s),elbow=a.names.indexOf('l_lowarm'),wrist=a.names.indexOf('l_wrist'),pos=m=>[m[3],m[7],m[11]],report={};
report.elbowPivotDisplacementMM=norm(sub(pos(r.targetPosedMatrices[elbow]),pos(z.targetRestMatrices[elbow])))*1000;report.forearmLengthDifferenceMM=Math.abs(norm(sub(pos(r.targetPosedMatrices[wrist]),pos(r.targetPosedMatrices[elbow])))-norm(sub(pos(z.targetRestMatrices[wrist]),pos(z.targetRestMatrices[elbow]))))*1000;assert.ok(report.elbowPivotDisplacementMM<.001);assert.ok(report.forearmLengthDifferenceMM<.001);
const tr=a.zeroState();tr.pose[0]=10;tr.pose[1]=5;tr.pose[2]=-3;const translated=a.evaluate(tr);report.rootTranslationErrorMM=0;for(let i=0;i<z.vertices.length;i++)report.rootTranslationErrorMM=Math.max(report.rootTranslationErrorMM,1000*Math.abs(translated.vertices[i]-z.vertices[i]-[1,.3,.5][i%3]));assert.ok(report.rootTranslationErrorMM<.001);
const snapshot=a.exportSnapshot(r);report.exportSnapshotMaxRoundTripMM=0;const w=r.skinWeights;for(let i=0;i<a.bodyCount;i++){const p=Array.from(r.vertices.slice(i*3,i*3+3)),sum=[0,0,0];for(let k=w.ptr[i];k<w.ptr[i+1];k++){const j=w.joints[k],q=point(mul(snapshot.jointWorld[j],snapshot.inverseSnapshotBindWorld[j]),p);for(let c=0;c<3;c++)sum[c]+=w.values[k]*q[c];}report.exportSnapshotMaxRoundTripMM=Math.max(report.exportSnapshotMaxRoundTripMM,1000*norm(sub(sum,p)));}assert.ok(report.exportSnapshotMaxRoundTripMM<1e-6);report.snapshotSemantics=snapshot.deformation;
fs.writeFileSync(new URL('kinematics-export-report.json',import.meta.url),JSON.stringify(report,null,2));console.log(report);
